using System;
using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
namespace ElswordPixel.CargoDirectorControlledV21 {
 [Serializable] sealed class SavedSceneInput {public string path;public bool isLoaded,isActive;}
 [Serializable] sealed class SavedSceneSetup {public SavedSceneInput[] scenes;}
 [Serializable] sealed class BootstrapInput {public string bootstrapSceneAssetPath;public InputPin bootstrapScene;}
 [Serializable] sealed class LoadedSceneEvidence {public string path,name;public int handle,rootObjects;public bool valid,loaded,active,dirty;}
 [Serializable] sealed class SceneSetupEvidence {public string phase,rawSetupJson;public SavedSceneInput[] rawSetup;public LoadedSceneEvidence[] runtimeScenes;public int setupCount,setupLoadedCount,setupActiveCount,runtimeSceneCount,runtimeLoadedCount,runtimeActiveCount;public bool isBatchMode;}
 [Serializable] sealed class EditorRunEvidence {public string phase,manifest,inputManifestSha256,output,shaderAssetPath,error,restoreTargetJson,initialSceneEvidenceJson,restoredSceneEvidenceJson,bootstrapSceneAssetPath;public int exitCode,probeExitCode;public bool actualPlayModeRequested,originalSetupWasEmpty,bootstrapUsed,restoreSucceeded,originalSavedSceneSetupRestored,projectColorSpaceModified=false,sharedSceneAssetModified=false;}
 [InitializeOnLoad] public static class CargoDirector2DControlledProbeV21 {
  const string Key="ElswordPixel.CargoDirectorControlledV21.";
  static CargoDirector2DControlledProbeV21(){EditorApplication.playModeStateChanged+=Changed;}
  static SavedSceneInput[] Save(SceneSetup[] raw){var a=new SavedSceneInput[raw.Length];for(int i=0;i<a.Length;i++)a[i]=new SavedSceneInput{path=raw[i].path,isLoaded=raw[i].isLoaded,isActive=raw[i].isActive};return a;}
  static SceneSetupEvidence Observe(string phase){
   SceneSetup[] raw=EditorSceneManager.GetSceneManagerSetup();var e=new SceneSetupEvidence{phase=phase,rawSetup=Save(raw),setupCount=raw.Length,isBatchMode=Application.isBatchMode,runtimeSceneCount=SceneManager.sceneCount};e.rawSetupJson=JsonUtility.ToJson(new SavedSceneSetup{scenes=e.rawSetup},true);foreach(var s in raw){if(s.isLoaded)e.setupLoadedCount++;if(s.isActive)e.setupActiveCount++;}var active=SceneManager.GetActiveScene();e.runtimeScenes=new LoadedSceneEvidence[e.runtimeSceneCount];for(int i=0;i<e.runtimeSceneCount;i++){Scene s=SceneManager.GetSceneAt(i);var r=new LoadedSceneEvidence{path=s.path,name=s.name,handle=s.handle,valid=s.IsValid(),loaded=s.isLoaded,active=active.IsValid()&&s.handle==active.handle,dirty=s.isDirty,rootObjects=s.isLoaded?s.GetRootGameObjects().Length:0};e.runtimeScenes[i]=r;if(r.loaded)e.runtimeLoadedCount++;if(r.active)e.runtimeActiveCount++;}return e;
  }
  static bool NoDirty(SceneSetupEvidence e){foreach(var s in e.runtimeScenes)if(s.dirty)return false;return true;}
  static bool ValidSavedSetup(SceneSetupEvidence e){if(e.setupCount==0||e.setupLoadedCount==0||e.setupActiveCount!=1||e.runtimeLoadedCount==0||e.runtimeActiveCount!=1)return false;foreach(var s in e.rawSetup)if(String.IsNullOrEmpty(s.path))return false;return NoDirty(e);}
  static bool EmptyBatchBootstrapAllowed(SceneSetupEvidence e){if(!e.isBatchMode||e.setupCount!=0||!NoDirty(e))return false;foreach(var s in e.runtimeScenes)if(!String.IsNullOrEmpty(s.path)||s.rootObjects!=0)return false;return true;}
  static void Write(string output,string name,object value){File.WriteAllText(Path.Combine(output,name),JsonUtility.ToJson(value,true));}
  public static void Run(){
   string output=Environment.GetEnvironmentVariable("EL_CARGO_DIRECTOR_CONTROLLED_OUTPUT");
   try{
    SessionState.SetBool(Key+"ownsOutput",false);if(EditorApplication.isPlayingOrWillChangePlaymode)throw new InvalidOperationException("Run requires edit mode");string manifest=Environment.GetEnvironmentVariable("EL_CARGO_DIRECTOR_CONTROLLED_INPUT");if(String.IsNullOrEmpty(manifest)||String.IsNullOrEmpty(output))throw new InvalidOperationException("Set controlled input and fresh output environment");manifest=Path.GetFullPath(manifest);output=Path.GetFullPath(output);if(Directory.Exists(output)||File.Exists(output))throw new InvalidOperationException("Refusing existing output: "+output);
    string project=Path.GetFullPath(Path.Combine(Application.dataPath,".."));var input=JsonUtility.FromJson<DirectorComponentInput>(File.ReadAllText(manifest));if(input==null||input.install==null||input.captures==null||input.captures.Length!=8||String.IsNullOrEmpty(input.reportRootRelative))throw new InvalidOperationException("Invalid manifest");string reports=Path.GetFullPath(Path.Combine(project,input.reportRootRelative));if(!output.StartsWith(reports+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Output outside controlled Reports root");
    foreach(var item in input.install){string dest=Path.GetFullPath(Path.Combine(project,item.assetPath));if(!dest.StartsWith(Path.GetFullPath(Application.dataPath)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Install target escapes Assets");if(CargoDirector2DControlledWorkerV21.Sha(File.ReadAllBytes(item.source.path))!=item.source.sha256||CargoDirector2DControlledWorkerV21.Sha(File.ReadAllBytes(dest))!=item.source.sha256)throw new InvalidOperationException("Source/installed bytes differ: "+item.assetPath);}
    Shader shader=Shader.Find(input.shaderName);if(input.shaderName!="Sprites/Default"||!shader||shader.name!=input.shaderName||!shader.isSupported||ShaderUtil.ShaderHasError(shader))throw new InvalidOperationException("Pinned shader missing/unsupported/compile error");
    Directory.CreateDirectory(output);SessionState.SetBool(Key+"ownsOutput",true);SessionState.SetString(Key+"output",output);SceneSetupEvidence initial=Observe("initial-before-any-scene-mutation");Write(output,"editor-initial-scene-setup.json",initial);SessionState.SetString(Key+"initial",JsonUtility.ToJson(initial));SessionState.SetBool(Key+"originalEmpty",initial.setupCount==0);SessionState.SetBool(Key+"bootstrapUsed",false);
    if(!NoDirty(initial))throw new InvalidOperationException("Dirty user scene detected; no scene saved or closed");
    if(initial.setupCount==0){
     if(!EmptyBatchBootstrapAllowed(initial))throw new InvalidOperationException("Empty SceneManagerSetup has nonempty/nonbatch runtime scene; explicit initial evidence saved, refusing bootstrap");var boot=JsonUtility.FromJson<BootstrapInput>(File.ReadAllText(manifest));if(boot==null||boot.bootstrapScene==null||String.IsNullOrEmpty(boot.bootstrapSceneAssetPath))throw new InvalidOperationException("Empty batch requires a pinned existing saved bootstrap scene");string expected=Path.GetFullPath(Path.Combine(project,boot.bootstrapSceneAssetPath));if(!expected.StartsWith(Path.GetFullPath(Application.dataPath)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||expected!=Path.GetFullPath(boot.bootstrapScene.path)||CargoDirector2DControlledWorkerV21.Sha(File.ReadAllBytes(expected))!=boot.bootstrapScene.sha256)throw new InvalidOperationException("Bootstrap scene pin/path mismatch");
     // Open an existing saved scene only in edit mode. No SaveScene call and
     // no game scene is entered in play. This is an explicit recovery target
     // for an original batch state that had no valid restorable setup.
     EditorSceneManager.OpenScene(boot.bootstrapSceneAssetPath,OpenSceneMode.Single);SessionState.SetBool(Key+"bootstrapUsed",true);SessionState.SetString(Key+"bootstrapAsset",boot.bootstrapSceneAssetPath);SessionState.SetString(Key+"bootstrapPath",boot.bootstrapScene.path);SessionState.SetString(Key+"bootstrapSha",boot.bootstrapScene.sha256);
    }
    SceneSetupEvidence target=Observe("saved-clean-recovery-target-before-isolated-play");Write(output,"editor-recovery-scene-setup.json",target);if(!ValidSavedSetup(target))throw new InvalidOperationException("Recovery target requires at least1loaded and exactly1active saved clean scene");
    string targetJson=JsonUtility.ToJson(new SavedSceneSetup{scenes=target.rawSetup});SessionState.SetString(Key+"manifest",manifest);SessionState.SetString(Key+"setup",targetJson);SessionState.SetInt(Key+"exit",1);SessionState.SetString(Key+"phase","entering");Write(output,"editor-preflight.json",new EditorRunEvidence{phase="verified-explicit-recovery-target-entering-isolated-empty-play",manifest=manifest,inputManifestSha256=CargoDirector2DControlledWorkerV21.Sha(File.ReadAllBytes(manifest)),output=output,shaderAssetPath=input.shaderName,restoreTargetJson=targetJson,initialSceneEvidenceJson=JsonUtility.ToJson(initial),originalSetupWasEmpty=initial.setupCount==0,bootstrapUsed=SessionState.GetBool(Key+"bootstrapUsed",false),bootstrapSceneAssetPath=SessionState.GetString(Key+"bootstrapAsset",""),actualPlayModeRequested=true});EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);EditorApplication.isPlaying=true;
   }catch(Exception e){Fail(e,output);}
  }
  static void Changed(PlayModeStateChange state){string phase=SessionState.GetString(Key+"phase","");if(String.IsNullOrEmpty(phase))return;try{if(state==PlayModeStateChange.EnteredPlayMode&&phase=="entering"){string manifest=SessionState.GetString(Key+"manifest","");var input=JsonUtility.FromJson<DirectorComponentInput>(File.ReadAllText(manifest));Shader shader=Shader.Find(input.shaderName);SessionState.SetString(Key+"phase","running");var go=new GameObject("Standalone Cargo director2D controlled worker");go.hideFlags=HideFlags.DontSave;go.AddComponent<CargoDirector2DControlledWorkerV21>().Begin(manifest,SessionState.GetString(Key+"output",""),shader,Completed);}else if(state==PlayModeStateChange.EnteredEditMode&&(phase=="exiting"||phase=="failed"))RestoreAndFinish();}catch(Exception e){Fail(e,SessionState.GetString(Key+"output",""));}}
  static void Completed(int code){SessionState.SetInt(Key+"exit",code);SessionState.SetString(Key+"phase","exiting");EditorApplication.isPlaying=false;}
  static void RestoreAndFinish(){
   int probeCode=SessionState.GetInt(Key+"exit",1),code=probeCode;string output=SessionState.GetString(Key+"output","");string setupJson=SessionState.GetString(Key+"setup","");bool boot=SessionState.GetBool(Key+"bootstrapUsed",false);SessionState.SetString(Key+"phase","");string error=null;SceneSetupEvidence restored=null;bool recovered=false;
   try{
    var setup=JsonUtility.FromJson<SavedSceneSetup>(setupJson);if(setup==null||setup.scenes==null||setup.scenes.Length==0)throw new InvalidOperationException("Refusing invalid/empty recovery setup");var restore=new SceneSetup[setup.scenes.Length];int loaded=0,active=0;for(int i=0;i<restore.Length;i++){var s=setup.scenes[i];if(String.IsNullOrEmpty(s.path))throw new InvalidOperationException("Recovery scene has no saved path");restore[i]=new SceneSetup{path=s.path,isLoaded=s.isLoaded,isActive=s.isActive};if(s.isLoaded)loaded++;if(s.isActive)active++;}if(loaded==0||active!=1)throw new InvalidOperationException("Recovery setup requires loaded>=1, active==1");EditorSceneManager.RestoreSceneManagerSetup(restore);restored=Observe("actual-after-restore");Write(output,"editor-restored-scene-setup.json",restored);if(!ValidSavedSetup(restored)||restored.rawSetup.Length!=setup.scenes.Length)throw new InvalidOperationException("Actual restored scene layout is not valid/matching");for(int i=0;i<setup.scenes.Length;i++)if(setup.scenes[i].path!=restored.rawSetup[i].path||setup.scenes[i].isLoaded!=restored.rawSetup[i].isLoaded||setup.scenes[i].isActive!=restored.rawSetup[i].isActive)throw new InvalidOperationException("Actual restored setup differs from explicit recovery target");if(boot&&CargoDirector2DControlledWorkerV21.Sha(File.ReadAllBytes(SessionState.GetString(Key+"bootstrapPath","")))!=SessionState.GetString(Key+"bootstrapSha",""))throw new InvalidOperationException("Existing bootstrap scene Asset changed");recovered=true;
   }catch(Exception e){code=1;error=e.ToString();Debug.LogError(e);}
   string phase=recovered?(boot?"retained-saved-bootstrap-for-original-empty-batch":"restored-original-saved-scene-setup"):"restore-failed";Write(output,"editor-completed.json",new EditorRunEvidence{phase=phase,error=error,exitCode=code,probeExitCode=probeCode,output=output,restoreTargetJson=setupJson,initialSceneEvidenceJson=SessionState.GetString(Key+"initial",""),restoredSceneEvidenceJson=restored==null?null:JsonUtility.ToJson(restored),originalSetupWasEmpty=SessionState.GetBool(Key+"originalEmpty",false),bootstrapUsed=boot,bootstrapSceneAssetPath=SessionState.GetString(Key+"bootstrapAsset",""),restoreSucceeded=recovered,originalSavedSceneSetupRestored=recovered&&!boot});SessionState.SetBool(Key+"ownsOutput",false);if(Application.isBatchMode)EditorApplication.Exit(code);else Debug.Log("Cargo director2D controlled probe completed: "+output+" exit="+code);
  }
  static void Fail(Exception e,string output){if(SessionState.GetBool(Key+"ownsOutput",false)&&!String.IsNullOrEmpty(output)&&Directory.Exists(output))Write(output,"editor-error.json",new EditorRunEvidence{phase="failed",error=e.ToString(),output=output,exitCode=1,initialSceneEvidenceJson=SessionState.GetString(Key+"initial","")});Debug.LogError(e);string phase=SessionState.GetString(Key+"phase","");if(!String.IsNullOrEmpty(phase)){SessionState.SetInt(Key+"exit",1);SessionState.SetString(Key+"phase","failed");if(EditorApplication.isPlayingOrWillChangePlaymode)EditorApplication.isPlaying=false;else RestoreAndFinish();}else if(Application.isBatchMode)EditorApplication.Exit(1);}
 }
}
